  nybooks_alex: { label: "Lewis & Lloyd-Jones, 'The Vanished Library', New York Review of Books", url: "http://www.nybooks.com/articles/3517" },
  alexandria: { label: "Wikipedia: Library of Alexandria", url: "https://en.wikipedia.org/wiki/Library_of_Alexandria" },
  gozo: { label: "The Malta Independent: documents from Gozo dating to 1431 saved from the bin", url: "https://web.archive.org/web/20190506001141/http://www.independent.com.mt/articles/2015-05-23/local-news/Documents-from-Gozo-dating-to-1431-saved-from-the-bin-6736135676" },
  zaluski: { label: "Witt, 'The Strange Life of One of the Greatest European Libraries of the Eighteenth Century', FYI France", url: "https://web.archive.org/web/20210301040701/https://www.fyifrance.com/f102005c.htm" },
  loc: { label: "Library of Congress: Jefferson's Legacy \u2014 a brief history", url: "https://www.loc.gov/loc/legacy/loc.html" },
