  sikh: { label: "Indian Express: the mystery of the missing articles of the Sikh Reference Library", url: "https://web.archive.org/web/20201225164840/https://indianexpress.com/article/explained/the-mystery-of-missing-articles-of-sikh-reference-library-5789595/" },
  riedlmayer_erasing: { label: "Riedlmayer, 'Erasing the Past: The Destruction of Libraries and Archives in Bosnia-Herzegovina' (1995)", url: "https://web.archive.org/web/20120118204551/http://fp.arizona.edu/mesassoc/Bulletin/bosnia.htm" },
  riedlmayer_crimes: { label: "Riedlmayer, 'Crimes of war, crimes of peace', Library Trends 56(1)", url: "https://doi.org/10.1353%2Flib.2007.0057", note: "Peer-reviewed; basis of ICTY testimony." },
  harvard: { label: "Harvard Gazette: cataloguing cultural destruction in the Balkans", url: "https://news.harvard.edu/gazette/story/2020/02/harvard-librarian-puts-this-war-crime-on-the-map" },
  nub: { label: "University of Sarajevo: anniversary of the City Hall destruction", url: "https://unsa.ba/en/node/2708" },
  bih_court: { label: "Court of Bosnia & Herzegovina: custody of the suspects terminated", url: "http://www.sudbih.gov.ba/?id=3190&jezik=e" },
  bbc_iraq: { label: "BBC: prized Iraqi annals 'lost in blaze'", url: "https://news.bbc.co.uk/2/hi/middle_east/2948021.stm" },
  guardian_isis: { label: "The Guardian: ISIS destroys thousands of books and manuscripts in Mosul libraries", url: "https://www.theguardian.com/books/2015/feb/26/isis-destroys-thousands-books-libraries" },
