  elpais_egypt: { label: "El Pa\u00eds: fire during Cairo unrest destroys the original Description de l'\u00c9gypte", url: "https://web.archive.org/web/20210126031501/https://elpais.com/cultura/2011/12/18/actualidad/1324162801_850215.html", note: "In Spanish." },
  guardian_timbuktu: { label: "The Guardian: Timbuktu mayor says rebels torched library of historic manuscripts", url: "https://www.theguardian.com/world/2013/jan/28/mali-timbuktu-library-ancient-manuscripts", note: "The initial report; see the Foreign Policy piece for the correction." },
  fp_timbuktu: { label: "Foreign Policy: how many of Timbuktu's manuscripts were destroyed?", url: "https://foreignpolicy.com/2013/01/28/how-many-of-timbuktus-priceless-manuscripts-were-destroyed/", note: "The reporting that corrected the early 'everything was lost' headlines." },
  tyee: { label: "The Tyee: secret memo casts doubt on federal science library closures", url: "https://thetyee.ca/News/2013/12/30/Harper-Library-Closures/" },
  naharnet: { label: "Naharnet: Tripoli figures condemn torching of famed library", url: "http://www.naharnet.com/stories/en/112570-tripoli-figures-condemn-torching-famed-library-as-father-sarrouj-forgives-attackers" },
  lor_sa: { label: "Lor, 'Burning Libraries for the People', Libri 63(4)", url: "https://repository.up.ac.za/bitstream/handle/2263/37230/Lor_Burning_2013.pdf?sequence=3&isAllowed=y" },
  independent_ukzn: { label: "The Independent: 'Nazi-style' book burning at UKZN condemned", url: "https://www.independent.co.uk/news/world/africa/ukzn-south-africa-university-protests-nazistyle-library-book-burning-rape-brutality-a7230296.html" },
  bbc_bihar: { label: "BBC News: Bihar Sharif \u2014 the 113-year-old India library torched in a riot", url: "https://www.bbc.com/news/world-asia-india-65308394" },
  aljaz_bihar: { label: "Al Jazeera: India town mourns burning of historic library at Muslim school", url: "https://www.aljazeera.com/news/2023/4/10/india-town-mourns-burning-of-historic-library-at-muslim-school" },
  lap_gaza: { label: "Librarians and Archivists with Palestine: Israeli damage to archives, libraries and museums in Gaza", url: "https://librarianswithpalestine.org/gaza-report-2024/", note: "Field report, October 2023 \u2013 January 2024." },
  gaza_inv: { label: "Gaza, inventaire d'un patrimoine bombard\u00e9: Rashad al-Shawwa Cultural Center", url: "https://gazahistoire.hypotheses.org/3161", note: "In French." },
  gaza_wiki: { label: "Wikipedia: Destruction of cultural heritage during the Gaza war", url: "https://en.wikipedia.org/wiki/Destruction_of_cultural_heritage_during_the_Gaza_war" },
  sudan_wiki: { label: "Wikipedia: Destruction of cultural heritage during the Sudanese civil war", url: "https://en.wikipedia.org/wiki/Destruction_of_cultural_heritage_during_the_Sudanese_civil_war" },
  unesco_ua: { label: "UNESCO: verified damaged cultural sites in Ukraine", url: "https://www.unesco.org/en/ukraine-war/damaged-cultural-sites", note: "Updated continuously; figures here are as of 29 September 2026." },
