  abbey: { label: "Abbey Newsletter: the Leningrad library fire", url: "http://cool.conservation-us.org/byorg/abbey/an/an12/an12-4/an12-402.html" },
  bbc_norwich: { label: "BBC On This Day: library fire wipes out historic records (Norwich, 1994)", url: "https://news.bbc.co.uk/onthisday/hi/dates/stories/august/1/newsid_2526000/2526839.stm" },
  guardian_gsa: { label: "The Guardian: Glasgow School of Art fire damages the Mackintosh building", url: "https://www.theguardian.com/uk-news/2014/may/23/glasgow-school-art-fire-charles-rennie-mackintosh-live" },
  guardian_gsa2: { label: "The Guardian: Glasgow School of Art fire caused by gases from a foam canister", url: "https://www.theguardian.com/education/2014/nov/26/glasgow-school-of-art-fire-foam-canister-report" },
  scecsal_mzuzu: { label: "Dube, Kanyundo & Majawa, 'Coping with the fire disaster at Mzuzu University'", url: "https://www.scecsal.org/publications/papers2018/009_dube_2018.pdf" },
  ewn_jagger: { label: "Eyewitness News: fire wreaks destruction on UCT", url: "https://ewn.co.za/2021/04/18/fire-wreaks-massive-destruction-on-uct" },
  jagger_abd: { label: "Kirkwood, Noble & Singer, 'What we lost in the Jagger Library fire', Africa Bibliography", url: "https://doi.org/10.1017%2Fabd.2023.9" },
  qz_inion: { label: "Quartz: a Moscow library containing 14 million books is on fire", url: "http://qz.com/336926/a-moscow-library-containing-rare-un-documents-ancient-slavic-texts-and-14-million-books-is-on-fire/" },
